INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'YT-16-REELS-1: TikTok, Instagram Reels and Facebook Reels each have an official publishing API, and each needs an app the owner authorises',
'Pillar reach, program QNFO.REACH, roadmap YT-16 (yt-shorts-2026). Research 2026-11-04 from the platforms'' developer documentation. No path is automated against terms; all three are official APIs that need an app registered and authorised by the owner, so none can be started by the fleet alone.
- Instagram Reels: Instagram API content publishing (developers.facebook.com/docs/instagram-platform/content-publishing) takes a container with media_type=REELS and a public video URL, for a professional (business or creator) account; permissions instagram_basic + instagram_content_publish (Facebook Login) or instagram_business_content_publish (Instagram Login); 100 API-published posts per 24 hours. The R2 object would need a public URL (a signed or public qnfo-media path).
- Facebook Reels: the Pages API video_reels publishing flow on a Page the owner administers (pages_manage_posts); same app review route as Instagram.
- TikTok: Content Posting API (developers.tiktok.com/doc/content-posting-api-get-started): scope video.publish authorised by the account holder; posts of an unaudited app are restricted to private viewing until TikTok audits the app; the creator-info step and TikTok''s UX guidelines (the creator confirms each post and its disclosure settings) make unattended posting a terms question to read before building.
- Under YT-16 the native Bluesky video and Mastodon video posts from qnfo-social (SHORT-POSTS-1) are the automatable part and are built apart from this finding, inside the existing channel caps and suppression.
Next step: the owner creates the Meta app (Instagram + Facebook Reels) and, if wanted, the TikTok developer app, and authorises it; the fleet then adds a publisher behind the same gates as the Bluesky and Mastodon posts. Closing probe: social_video_posts holds a posted row with platform instagram, facebook or tiktok.
IDENTITY-BOUND: registering a developer app and authorising publishing on the owner''s own Instagram, Facebook and TikTok accounts is an act on the owner''s accounts; the fleet cannot do it and does not work around the platforms'' app review.',
'session:yt-distribution', 'optimization', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title = 'YT-16-REELS-1: TikTok, Instagram Reels and Facebook Reels each have an official publishing API, and each needs an app the owner authorises' AND status = 'open');
